const menu=document.querySelector('.menu');const nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.querySelector('span').textContent=open?'−':'＋'});
nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.querySelector('span').textContent='＋'}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){menu.click();menu.focus()}});
const essays={silence:{title:'침묵이 공간의 형태가 될 때',category:'SPATIAL CRITIQUE',body:['방 안에 아무것도 없다고 생각했을 때, 비로소 빛이 보였습니다. 벽을 따라 천천히 움직이는 그림자는 공간이 멈춰 있는 대상이 아니라 시간과 함께 달라지는 경험임을 알려줍니다.','여백은 비어 있는 면적만을 뜻하지 않습니다. 시선이 잠시 쉬어 갈 거리이자, 다음 감각을 받아들일 수 있는 틈입니다. 무엇을 더할지 묻기 전에 무엇이 이미 그곳에 있는지 바라보는 일. 공간에 대한 생각은 그 작은 멈춤에서 시작됩니다.','침묵에도 형태가 있다면, 그것은 삶을 밀어내지 않는 배경에 가까울 것입니다. 사람의 움직임과 숨결이 자연스럽게 드러나는 곳. 우리가 공간에서 찾는 조용함은 어쩌면 그런 여유인지도 모릅니다.']},walk:{title:'산책자가 머무는 자리',category:'FLÂNERIE',body:['걷는 속도에서만 읽히는 도시가 있습니다. 골목의 모퉁이에 놓인 의자, 오후의 그늘이 먼저 내려앉는 벽, 길과 가게 사이의 짧은 문턱. 목적지로 서둘러 향할 때는 지나쳤던 장면입니다.','산책자는 공간을 정해진 용도로만 읽지 않습니다. 잠시 기대어 서기 좋은 턱은 쉼터가 되고, 가로수 아래 빈자리는 계절을 느끼는 방이 됩니다. 도시는 계획된 기능과 우연한 사용 사이에서 풍성해집니다.','사람을 위한 공간을 생각할 때, 우리는 먼저 걸어볼 수 있습니다. 어디에서 발걸음이 느려지는지, 어떤 풍경 앞에 머물게 되는지. 몸의 속도로 얻은 질문은 도면 위의 선에 새로운 이유를 건넵니다.']},proportion:{title:'하이엔드의 본질',category:'NORDIC ESSENCE',body:['좋은 재료가 좋은 공간을 보장할까요. 손끝에 닿는 표면이 아름다워도 눈이 쉬지 못하거나 대화가 편안하지 않다면, 공간의 경험은 쉽게 흩어집니다.','우리는 때로 개별 사물보다 사물 사이의 관계를 오래 기억합니다. 의자와 창의 거리, 낮은 조명과 테이블의 비례, 몸을 감싸는 재료와 빛의 온도. 풍요로움은 더 많은 요소를 소유하는 데서보다 감각이 서로를 방해하지 않는 상태에서 찾아올 수 있습니다.','오래 머물고 싶은 공간의 기준은 결국 삶에 있습니다. 몸에 무리가 없는지, 마음이 편히 놓이는지, 시간이 지나도 그 자리를 찾고 싶은지. 공간의 가치는 매일의 작은 경험 속에서 천천히 드러납니다.']}};
const dialog=document.querySelector('dialog');let trigger;
function showEssay(){const key=new URLSearchParams(location.search).get('essay');const essay=essays[key];if(!essay){if(dialog.open)dialog.close();return}document.querySelector('#read-title').textContent=essay.title;document.querySelector('#read-category').textContent=essay.category;document.querySelector('#read-body').replaceChildren(...essay.body.map(text=>{const p=document.createElement('p');p.textContent=text;return p}));if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden'}
document.querySelectorAll('.essay').forEach(link=>link.addEventListener('click',e=>{e.preventDefault();trigger=link;history.pushState({essay:true},'',link.href);showEssay()}));
function closeEssay(){if(history.state?.essay){history.back()}else{const url=new URL(location.href);url.searchParams.delete('essay');history.replaceState(null,'',url);showEssay()}}
document.querySelector('.close').addEventListener('click',closeEssay);dialog.addEventListener('cancel',e=>{e.preventDefault();closeEssay()});dialog.addEventListener('close',()=>{document.body.style.overflow='';trigger?.focus()});window.addEventListener('popstate',showEssay);showEssay();
